package cli_test

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
)

// runCLI executes the CLI and captures output
// Simpler than genetic modifications. More predictable.
func runCLI(t *testing.T, args ...string) (stdout, stderr string, exitCode int) {
	t.Helper()
	cmd := exec.Command("./config-cli", args...)
	var outBuf, errBuf bytes.Buffer
	cmd.Stdout = &outBuf
	cmd.Stderr = &errBuf

	err := cmd.Run()
	exitCode = 0
	if exitErr, ok := err.(*exec.ExitError); ok {
		exitCode = exitErr.ExitCode()
	}
	return outBuf.String(), errBuf.String(), exitCode
}

func TestArgumentParsing(t *testing.T) {
	// Table-driven. Efficient. Like STG protocols.
	tests := []struct {
		name         string
		args         []string
		wantExit     int
		wantInStderr string
	}{
		{"valid init", []string{"init"}, 0, ""},
		{"valid get", []string{"get", "database.host"}, 0, ""},
		{"valid set", []string{"set", "database.host", "localhost"}, 0, ""},
		{"missing get key", []string{"get"}, 2, "requires key argument"},
		{"missing set value", []string{"set", "key"}, 2, "requires key and value"},
		{"unknown command", []string{"explode"}, 2, "unknown command"},
		{"invalid flag", []string{"--invalid"}, 2, "unknown flag"},
		{"conflicting flags", []string{"--quiet", "--verbose", "list"}, 2, "mutually exclusive"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, stderr, exit := runCLI(t, tt.args...)
			if exit != tt.wantExit {
				t.Errorf("exit = %d, want %d", exit, tt.wantExit)
			}
			if tt.wantInStderr != "" && !bytes.Contains([]byte(stderr), []byte(tt.wantInStderr)) {
				t.Errorf("stderr missing %q", tt.wantInStderr)
			}
		})
	}
}

func TestExitCodes(t *testing.T) {
	// Three states. Success. Error. Usage error. 
	// Like Genophage. Binary outcomes. Consequences.
	tmpDir := t.TempDir()
	configPath := filepath.Join(tmpDir, "config.yaml")

	tests := []struct {
		name     string
		setup    func()
		args     []string
		wantExit int
	}{
		{"success - init", nil, []string{"init", "--config", configPath}, 0},
		{"success - list", func() { os.WriteFile(configPath, []byte("key: value"), 0644) }, 
			[]string{"list", "--config", configPath}, 0},
		{"error - missing file", nil, 
			[]string{"get", "key", "--config", "/nonexistent/path"}, 1},
		{"usage error - no args to set", nil, []string{"set"}, 2},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if tt.setup != nil {
				tt.setup()
			}
			_, _, exit := runCLI(t, tt.args...)
			if exit != tt.wantExit {
				t.Errorf("exit = %d, want %d", exit, tt.wantExit)
			}
		})
	}
}

func TestOutputStreams(t *testing.T) {
	// Data to stdout. Errors to stderr. 
	// Separation of concerns. Like separating cure from delivery mechanism.
	tmpDir := t.TempDir()
	configPath := filepath.Join(tmpDir, "config.yaml")
	os.WriteFile(configPath, []byte("database:\n  host: localhost"), 0644)

	t.Run("data goes to stdout", func(t *testing.T) {
		stdout, stderr, _ := runCLI(t, "get", "database.host", "--config", configPath)
		if stdout == "" {
			t.Error("expected data on stdout")
		}
		if stderr != "" {
			t.Errorf("unexpected stderr: %s", stderr)
		}
	})

	t.Run("errors go to stderr", func(t *testing.T) {
		stdout, stderr, _ := runCLI(t, "get", "nonexistent", "--config", configPath)
		if stdout != "" {
			t.Errorf("unexpected stdout: %s", stdout)
		}
		if stderr == "" {
			t.Error("expected error on stderr")
		}
	})
}

func TestFileOperations(t *testing.T) {
	// File system. Permissions. Creation. 
	// Variables. Many variables.
	t.Run("init creates config file", func(t *testing.T) {
		tmpDir := t.TempDir()
		configPath := filepath.Join(tmpDir, "new", "config.yaml")
		_, _, exit := runCLI(t, "init", "--config", configPath)
		if exit != 0 {
			t.Fatalf("init failed with exit %d", exit)
		}
		if _, err := os.Stat(configPath); os.IsNotExist(err) {
			t.Error("config file not created")
		}
	})

	t.Run("permission denied", func(t *testing.T) {
		tmpDir := t.TempDir()
		os.Chmod(tmpDir, 0444) // Read-only
		defer os.Chmod(tmpDir, 0755)

		configPath := filepath.Join(tmpDir, "config.yaml")
		_, stderr, exit := runCLI(t, "init", "--config", configPath)
		if exit != 1 {
			t.Errorf("expected exit 1, got %d", exit)
		}
		if !bytes.Contains([]byte(stderr), []byte("permission")) {
			t.Error("expected permission error message")
		}
	})
}

func TestEdgeCases(t *testing.T) {
	// Edge cases. Where bugs hide. Like Collectors.
	// Must be thorough.
	tmpDir := t.TempDir()

	t.Run("invalid YAML syntax", func(t *testing.T) {
		badConfig := filepath.Join(tmpDir, "bad.yaml")
		os.WriteFile(badConfig, []byte("invalid: yaml: content:"), 0644)
		_, stderr, exit := runCLI(t, "validate", "--config", badConfig)
		if exit != 1 {
			t.Errorf("expected exit 1 for invalid YAML")
		}
		if !bytes.Contains([]byte(stderr), []byte("syntax")) {
			t.Error("error should mention syntax")
		}
	})

	t.Run("empty config file", func(t *testing.T) {
		emptyConfig := filepath.Join(tmpDir, "empty.yaml")
		os.WriteFile(emptyConfig, []byte(""), 0644)
		_, _, exit := runCLI(t, "list", "--config", emptyConfig)
		if exit != 0 {
			t.Error("empty config should be valid")
		}
	})
}
